def median(values):
    """Middle value of a non-empty sequence, sorted first."""
    values = sorted(values)
    if not values:
        raise ValueError("median of an empty sequence")
    mid = len(values) // 2
    if len(values) % 2:
        return values[mid]
    return mean(values[mid - 1:mid + 1])

